#include <vector>
#include <algorithm>

class Solution {
public:
    int maxFreeTime(int eventTime, std::vector<int>& startTime, std::vector<int>& endTime) {
        int n = startTime.size();
        std::vector<int> gaps;
        gaps.reserve(n + 1);
        gaps.push_back(startTime[0]);
        for (int i = 1; i < n; ++i) {
            gaps.push_back(startTime[i] - endTime[i - 1]);
        }
        gaps.push_back(eventTime - endTime[n - 1]);

        int m = gaps.size();
        std::vector<int> pref(m, 0), suff(m, 0);
        pref[0] = gaps[0];
        for (int i = 1; i < m; ++i) pref[i] = std::max(pref[i - 1], gaps[i]);
        suff[m - 1] = gaps[m - 1];
        for (int i = m - 2; i >= 0; --i) suff[i] = std::max(suff[i + 1], gaps[i]);

        int ans = *std::max_element(gaps.begin(), gaps.end());
        for (int i = 0; i < n; ++i) {
            int dur = endTime[i] - startTime[i];
            ans = std::max(ans, gaps[i] + gaps[i + 1]);
            int outside = 0;
            if (i > 0) outside = std::max(outside, pref[i - 1]);
            if (i + 2 < m) outside = std::max(outside, suff[i + 2]);
            if (outside >= dur) {
                ans = std::max(ans, gaps[i] + gaps[i + 1] + dur);
            }
        }
        return ans;
    }
};

class Solution {
    public int maxFreeTime(int eventTime, int[] startTime, int[] endTime) {
        int n = startTime.length;
        int[] gaps = new int[n + 1];
        gaps[0] = startTime[0];
        for (int i = 1; i < n; i++) {
            gaps[i] = startTime[i] - endTime[i - 1];
        }
        gaps[n] = eventTime - endTime[n - 1];

        int m = n + 1;
        int[] pref = new int[m];
        int[] suff = new int[m];
        pref[0] = gaps[0];
        for (int i = 1; i < m; i++) pref[i] = Math.max(pref[i - 1], gaps[i]);
        suff[m - 1] = gaps[m - 1];
        for (int i = m - 2; i >= 0; i--) suff[i] = Math.max(suff[i + 1], gaps[i]);

        int ans = 0;
        for (int g : gaps) ans = Math.max(ans, g);
        for (int i = 0; i < n; i++) {
            int dur = endTime[i] - startTime[i];
            ans = Math.max(ans, gaps[i] + gaps[i + 1]);
            int outside = 0;
            if (i > 0) outside = Math.max(outside, pref[i - 1]);
            if (i + 2 < m) outside = Math.max(outside, suff[i + 2]);
            if (outside >= dur) {
                ans = Math.max(ans, gaps[i] + gaps[i + 1] + dur);
            }
        }
        return ans;
    }
}

var maxFreeTime = function(eventTime, startTime, endTime) {
    const n = startTime.length;
    const gaps = new Int32Array(n + 1);
    gaps[0] = startTime[0];
    for (let i = 1; i < n; i++) {
        gaps[i] = startTime[i] - endTime[i - 1];
    }
    gaps[n] = eventTime - endTime[n - 1];

    const m = n + 1;
    const pref = new Int32Array(m);
    const suff = new Int32Array(m);
    pref[0] = gaps[0];
    for (let i = 1; i < m; i++) pref[i] = Math.max(pref[i - 1], gaps[i]);
    suff[m - 1] = gaps[m - 1];
    for (let i = m - 2; i >= 0; i--) suff[i] = Math.max(suff[i + 1], gaps[i]);

    let ans = 0;
    for (let i = 0; i < m; i++) {
        if (gaps[i] > ans) ans = gaps[i];
    }
    for (let i = 0; i < n; i++) {
        const dur = endTime[i] - startTime[i];
